<script setup lang="ts">
// Three sacred Tree of Wisdom entrances on /demo/?prototype=wisdom&variant=A|B|C.
import { shallowRef,computed,onMounted,onBeforeUnmount } from 'vue';
import logo from '../../../shared/assets/logo-clear.svg';
import night from './assets/sacred-tree-night.png';
import dawn from './assets/sacred-tree-dawn.png';
import { books } from './books';
import CanopyVariant from './CanopyVariant.vue';
import CelestialVariant from './CelestialVariant.vue';
import SanctuaryVariant from './SanctuaryVariant.vue';
import BookPreview from './BookPreview.vue';
import BookCover from './BookCover.vue';
import ArrivalTransition from './ArrivalTransition.vue';
type Variant='A'|'B'|'C';
const params=new URLSearchParams(location.search);
const variant=shallowRef<Variant>((['A','B','C'].includes(params.get('variant')||'')?params.get('variant'):'C') as Variant);
const selected=shallowRef<string|null>(books.some(b=>b.id===params.get('book'))?params.get('book'):null);
const scene=shallowRef('tree'),search=shallowRef(''),onlyMine=shallowRef(false),summoned=shallowRef(['analysis']);
const arrival=shallowRef(params.get('arrival')!=='0'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const chosenBook=computed(()=>books.find(b=>b.id===selected.value));
const shown=computed(()=>books.filter(b=>(!onlyMine.value||summoned.value.includes(b.id))&&`${b.title} ${b.subject}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const currentComponent=computed(()=>({A:CanopyVariant,B:CelestialVariant,C:SanctuaryVariant})[variant.value]);
const variantNames={A:'The sacred grove',B:'The celestial tree',C:'The sanctuary'};
const moteStyles=Array.from({length:25},(_,i)=>({left:`${(i*47+13)%100}%`,top:`${(i*31+17)%100}%`,animationDelay:`${-i*.7}s`,animationDuration:`${10+i%7}s`,width:i%3===0?'3px':'2px',height:i%3===0?'3px':'2px'}));
function url(){const p=new URLSearchParams(location.search);p.set('prototype','wisdom');p.set('variant',variant.value);selected.value?p.set('book',selected.value):p.delete('book');history.replaceState(null,'',`${location.pathname}?${p}`)}
function changeVariant(value:Variant){variant.value=value;scene.value='tree';url()}
function cycle(step:number){const list:Variant[]=['A','B','C'];changeVariant(list[(list.indexOf(variant.value)+step+3)%3])}
function select(id:string){selected.value=id;url()}
function close(){selected.value=null;scene.value='tree';url()}
function summon(){if(selected.value&&!summoned.value.includes(selected.value))summoned.value=[...summoned.value,selected.value]}
function onKey(e:KeyboardEvent){if(arrival.value)return;if((e.target as Element)?.closest('input,textarea,[contenteditable=true],select'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft'){e.preventDefault();cycle(-1)}if(e.key==='ArrowRight'){e.preventDefault();cycle(1)}}
onMounted(()=>{document.title='Tree of Wisdom · Theumst prototype';const favicon=document.createElement('link');favicon.rel='icon';favicon.href=logo;favicon.id='wisdom-favicon';document.head.append(favicon);window.addEventListener('keydown',onKey)});
onBeforeUnmount(()=>{window.removeEventListener('keydown',onKey);document.getElementById('wisdom-favicon')?.remove()});
</script>
<template>
 <main class="wisdom-prototype" :class="['variant-'+variant,{'has-selection':!!chosenBook}]">
  <div class="scene-art" aria-hidden="true"><img v-show="variant==='A'" :src="night" alt="" class="night-art"><img v-show="variant==='C'" :src="dawn" alt="" class="dawn-art"><div class="scene-shade"></div><div class="motes"><i v-for="(style,i) in moteStyles" :key="i" :style="style"></i></div></div>
  <header class="wisdom-header"><button class="brand" aria-label="Return to Tree of Wisdom" @click="close"><img :src="logo" alt="UMST"><span class="wordmark">theumst<small>A PLACE TO LEARN</small></span></button><div class="header-actions"><label class="tree-search"><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8" cy="8" r="5.5"/><path d="m12 12 5 5"/></svg><input v-model="search" aria-label="Find a grimoire" placeholder="Find a grimoire" @input="scene='tree'"></label><button class="collection-toggle" :aria-pressed="onlyMine" @click="onlyMine=!onlyMine;scene='tree'">{{onlyMine?'All grimoires':'My grimoires'}}<span>{{summoned.length}}</span></button></div></header>
  <template v-if="scene==='tree'">
   <component :is="currentComponent" :books="shown" :selected="selected" @select="select"/>
   <div v-if="shown.length===0" class="no-books"><span>✧</span><h2>No grimoire by that name.</h2><button @click="search='';onlyMine=false">Show all grimoires</button></div>
   <Transition name="preview"><div v-if="chosenBook" class="preview-position"><BookPreview :key="chosenBook.id" :book="chosenBook" :summoned="summoned.includes(chosenBook.id)" @close="close" @summon="summon" @enter="scene='realms'"/></div></Transition>
  </template>
  <section v-else-if="chosenBook" class="next-scene" aria-label="Next scene placeholder"><BookCover :book="chosenBook"/><p class="next-kicker">{{chosenBook.subject}}</p><h1>{{chosenBook.title}}</h1><p>Your grimoire is ready.</p><button @click="scene='tree'">← Return to the tree</button><span class="next-note">Realms will be designed in the next scene.</span></section>
  <a class="leave-link" href="https://theumst.com/">↙ Homepage</a>
  <button class="replay-arrival" @click="arrival=true">↑ Replay arrival</button>
  <aside class="prototype-switcher" aria-label="Prototype variants"><div class="switcher-controls"><button class="cycle" aria-label="Previous prototype" @click="cycle(-1)">‹</button><div class="variant-options"><button v-for="v in (['A','B','C'] as const)" :key="v" :aria-label="'Variant '+v+': '+variantNames[v]" :aria-pressed="variant===v" @click="changeVariant(v)">{{v}}</button></div><span class="variant-name">{{variantNames[variant]}}</span><button class="cycle" aria-label="Next prototype" @click="cycle(1)">›</button></div><p class="prototype-state">PROTOTYPE · {{scene==='tree'?'Tree of Wisdom':'Realms · next scene'}} · {{chosenBook?.short||'Choose a grimoire'}} · {{summoned.length}} summoned<span v-if="search"> · “{{search}}”</span><span v-if="onlyMine"> · My grimoires</span></p></aside>
  <ArrivalTransition v-if="arrival" :destination="variant==='C'?dawn:night" :celestial="variant==='B'" :sanctuary="variant==='C'" @done="arrival=false"/>
 </main>
</template>
<style>
