eight:23px;cursor:pointer}.variant-options button[aria-pressed=true]{background:#e9e2ce;color:#244855;border-color:#f5ead4}.variant-name{font:12px Georgia,serif;min-width:140px;text-align:center;flex:1}.prototype-state{font:8px/1.5 'Courier New',monospace;color:#99b1b8;text-align:center;margin:5px 0 0;max-width:520px}.leave-link{position:absolute;z-index:5;bottom:37px;left:33px;font:10px 'Courier New',monospace;color:#cad0c9;text-decoration:none}.variant-C .leave-link{color:#626b5c}.leave-link:hover{text-decoration:underline}.no-books{position:absolute;z-index:6;top:47%;left:50%;transform:translate(-50%,-50%);background:#122839ed;color:#e7ddc5;border:1px solid #63737b;padding:30px;text-align:center;box-shadow:0 10px 80px #0b16235a}.no-books>span{font-size:25px}.no-books h2{font:24px Georgia,serif}.no-books button,.next-scene button{background:#eae6d6;color:#314d58;border:1px solid #9caaa7;padding:10px 15px;cursor:pointer;font:11px 'Courier New',monospace}.next-scene{position:absolute;z-index:4;inset:110px 10% 115px;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#152a3ae8;border:1px solid #8b9d9666;backdrop-filter:blur(14px);color:#efebdc}.next-kicker{font:9px 'Courier New',monospace;text-transform:uppercase;letter-spacing:.2em;color:#b6bbad;margin:32px 0 10px}.next-scene h1{font:34px/1.2 Georgia,serif;letter-spacing:-.02em;margin:0;text-align:center}.next-scene>p:not(.next-kicker){font:14px Georgia,serif;color:#b5c3c1;margin:12px 0 25px}.next-note{font:10px 'Courier New',monospace;color:#9dafb1;margin-top:23px}.variant-C .next-scene{background:#f7f1e4e8;color:#505745}.variant-C .next-scene p,.variant-C .next-note{color:#7c836e}@keyframes drift{0%,100%{opacity:0;transform:translate(0,5px)}40%{opacity:.35}70%{opacity:.18}100%{transform:translate(13px,-38px)}}@media(max-width:1000px){.wisdom-header{padding:21px}.preview-position{right:23px}.has-selection .header-actions{opacity:.3;pointer-events:none}.leave-link{left:22px;bottom:100px}}@media(max-width:700px){.wisdom-prototype{min-height:700px}.wisdom-header{padding:18px;gap:12px}.brand img{width:30px;height:35px}.wordmark{font-size:23px}.wordmark small{font-size:5px}.header-actions{gap:10px}.tree-search{position:absolute;right:19px;top:76px}.tree-search input{width:123px;font-size:10px}.collection-toggle{font-size:9px;padding:9px}.preview-position{left:16px;right:16px;top:109px}.prototype-switcher{min-width:0;width:calc(100% - 34px);max-width:430px;bottom:18px;padding:7px}.switcher-controls{gap:5px}.variant-name{font-size:11px;min-width:90px}.prototype-state{font-size:7px}.leave-link{bottom:96px;left:21px;font-size:9px}.next-scene{inset:110px 16px 110px}.next-scene h1{font-size:25px}.next-note{font-size:8px}.scene-art .night-art{object-position:58% 50%}.scene-art .dawn-art{object-position:23% 50%}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
